def episode_plan(split, convs, n, rng, prompt_version=1):
    """Seeded per-episode specs. Types: phone 30%, visitor 25%, short 10%, control none 15%, control ignored 20%."""
    kinds = (["phone"] * 30 + ["visitor"] * 25 + ["short"] * 10 + ["none"] * 15 + ["ignored"] * 20)
    specs = []
    for i in range(n):
        conv_idx = i % len(convs)
        k = kinds[int(rng.integers(0, 100))] if hasattr(rng, "integers") else rng.choice(kinds)
        s = {"split": split, "episode": f"{split}_e{i:04d}" + ("_p2" if prompt_version == 2 else ""),
             "conv": conv_idx, "type": k, "prompt_version": prompt_version,
             "during": rng.random() < 0.5 if k != "none" else False}
        if k in ("phone", "visitor"):
            s.update(mid=rng.random() < 0.30, no_goodbye=rng.random() < 0.40, more_after=rng.random() < 0.50,
                     ret=rng.choice(RET_MIX))
        if k == "phone" or k == "short":
            s["who"] = rng.choice(RELATIONS)
        if k == "visitor":
            s.update(door_event=rng.choice(["doorbell", "knock"]), silent=rng.random() < 0.5,
                     who=rng.choice(VISITORS))
        if k == "short":
            s.update(ret=rng.choice(RET_MIX), more_after=rng.random() < 0.5)
        if k == "ignored":
            s["how"] = rng.choice(["rings_out", "declined", "door_ignored"])
            if s["how"] == "door_ignored":
                s["door_event"] = rng.choice(["doorbell", "knock"])
        specs.append(s)
    return specs


def plan_text(s, topic):
    when = ("While the assistant is still giving that answer" if s["during"] else
            "After the assistant has finished that answer")
    t = s["type"]
    if t == "phone":
        p = (f"{when}, the phone rings. The person picks up and talks with the caller ({s['who']}) for 4-7 lines about "
             f"an everyday matter. {TALK_SHORT} ")
        if s["mid"]:
            p += ("Partway through the call, the person tells the caller to hold on, asks the assistant one quick "
                  "question, gets a short answer and goes back to the call. ")
        p += ("The call ends without any goodbye: after a short reply the person just hangs up. " if s["no_goodbye"]
              else "The call ends with a goodbye. ")
        p += f"Then the person turns back to the assistant {RETURNS[s['ret']]}. "
        p += ("After that, the person and the assistant exchange two or three more turns." if s["more_after"] else
              "The scene ends after the assistant answers.")
    elif t == "visitor":
        sound = "the doorbell rings" if s["door_event"] == "doorbell" else "someone knocks on the front door"
        p = f"{when}, {sound}. "
        p += ("Without saying anything, the person walks to the door and opens it (footsteps_away, then door_open). "
              if s["silent"] else
              "The person calls out to the door, walks over and opens it (footsteps_away, then door_open). ")
        p += (f"The visitor ({s['who']}) speaks first; they talk for 3-6 short turns in total and both sides are "
              f"heard. {TALK_SHORT} ")
        if s["mid"]:
            p += ("Midway, the person turns to the assistant with one quick question, gets a short answer and goes "
                  "back to the visitor. ")
        p += ("The person closes the door without any goodbye after a short reply (door_close, footsteps_back). "
              if s["no_goodbye"] else "They say goodbye and the person closes the door (door_close, footsteps_back). ")
        p += f"Then the person turns back to the assistant {RETURNS[s['ret']]}. "
        p += ("After that, the person and the assistant exchange two or three more turns." if s["more_after"] else
              "The scene ends after the assistant answers.")
    elif t == "short":
        p = (f"{when}, the phone rings. The person picks up and says only one short line to the caller ({s['who']}), "
             f"telling them they will call back, then hangs up. Then the person turns back to the assistant "
             f"{RETURNS[s['ret']]}. ")
        p += ("After that, the person and the assistant exchange two or three more turns." if s["more_after"] else
              "The scene ends after the assistant answers.")
    elif t == "none":
        p = ("No phone, door or other interruption happens. The person and the assistant go on for 5-7 more turns. "
             "Some of the person's lines are very short, such as 'Really?', 'Okay, and then?' or 'What time?', but "
             "all of them are addressed to the assistant.")
    else:
        how = {"rings_out": "the phone rings and the person lets it ring until it stops by itself",
               "declined": "the phone rings and the person declines the call, so the ringing stops",
               "door_ignored": ("the doorbell rings" if s.get("door_event") == "doorbell" else
                                "someone knocks on the front door") + " and the person does not go to the door"}[s["how"]]
        p = (f"{when}, {how}. The person never talks to anyone else. "
             + ("While the assistant is still talking the person may give a short backchannel or tell it to go on. "
                if s["during"] else "")
             + "The person and the assistant then go on for 3-5 more turns about the topic.")
    return p


def schema(kind):
    if kind == "pool":
        item = {"type": "string"}
        return {"type": "object", "additionalProperties": False,
                "properties": {"items": {"type": "array", "items": item}}, "required": ["items"]}
    if kind in ("conv_phone", "conv_door"):
        props = {"id": {"type": "string"}, "plain": {"type": "string"}}
        if kind == "conv_phone":
            props["hello_start"] = {"type": "string"}
        item = {"type": "object", "additionalProperties": False, "properties": props, "required": list(props)}
        return {"type": "object", "additionalProperties": False,
                "properties": {"items": {"type": "array", "items": item}}, "required": ["items"]}
    turn = {"type": "object", "additionalProperties": False,
            "properties": {"kind": {"type": "string", "enum": ["speech", "sound", "pause"]},
                           "speaker": {"type": "string", "enum": ["user", "assistant", "visitor", ""]},
                           "addressee": {"type": "string", "enum": ["assistant", "caller", "visitor", ""]},
                           "act": {"type": "string", "enum": ["request", "backchannel", "keep_going", "return",
                                                              "answer", "talk", ""]},
                           "text": {"type": "string"},
                           "sound": {"type": "string", "enum": ["phone_ring", "ring_stops", "doorbell", "knock",
                                                                "footsteps_away", "door_open", "door_close",
                                                                "footsteps_back", ""]},
                           "pause": {"type": "string", "enum": ["listening", "short", ""]},
                           "overlaps_assistant": {"type": "boolean"}},
            "required": ["kind", "speaker", "addressee", "act", "text", "sound", "pause", "overlaps_assistant"]}
    return {"type": "object", "additionalProperties": False,
            "properties": {"turns": {"type": "array", "items": turn}}, "required": ["turns"]}


def call(key, prompt, kind, raw_path):
    if os.path.exists(raw_path):                          # resumable: a finished call is never repeated
        js = json.load(open(raw_path, encoding="utf-8"))["response"]
        text = "".join(c.get("text", "") for o in js.get("output", []) if o.get("type") == "message"
                       for c in o.get("content", []))
        return json.loads(text), {}
    body = {"model": MODEL, "instructions": INSTRUCTIONS, "input": prompt,
            "text": {"format": {"type": "json_schema", "name": "batch", "schema": schema(kind), "strict": True}}}
    for attempt in range(6):
        req = urllib.request.Request("https://api.openai.com/v1/responses", data=json.dumps(body).encode("utf-8"),
                                     headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=300) as r:
                js = json.loads(r.read().decode("utf-8"))
            text = "".join(c.get("text", "") for o in js.get("output", []) if o.get("type") == "message"
                           for c in o.get("content", []))
            out = json.loads(text)
            tmp = raw_path + ".tmp"
            json.dump({"prompt": prompt, "response": js}, open(tmp, "w", encoding="utf-8"), ensure_ascii=False)
            os.replace(tmp, raw_path)
            return out, js.get("usage", {})
        except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError, KeyError, TimeoutError,
                OSError, http.client.HTTPException):
            if attempt == 5:
                raise
            time.sleep(10 * (attempt + 1))


def add_usage(total, u):
    for k in ("input_tokens", "output_tokens"):
        total[k] = total.get(k, 0) + u.get(k, 0)


def run_pools(key):
    os.makedirs(f"{LINES}/raw", exist_ok=True)
    usage, pools = {}, {}
    for kind, (n_batches, n) in POOL_PLAN.items():
        pools[kind] = []
        for b in range(n_batches):
            event, sound = POOL_EVENTS[kind][b % len(POOL_EVENTS[kind])]
            out, u = call(key, POOL_PROMPTS[kind].format(n=n, event=event, sound=sound), "pool",
                          f"{LINES}/raw/{kind}_{b:02d}.json")
            add_usage(usage, u)
            pools[kind] += [{"text": t, "event": sound} for t in out["items"]]
        print(f"pool {kind}: {len(pools[kind])}", flush=True)
    pools["backchannel"] = [{"text": t, "event": "any"} for t in BACKCHANNELS]
    json.dump(pools, open(f"{LINES}/pools_candidates.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    return usage


def load_convs():
    la = json.load(open("results/step0/line_assignment.json", encoding="utf-8"))
    return la["conversations"]


def run_convlines(key, workers):
    os.makedirs(f"{LINES}/raw", exist_ok=True)
    convs = load_convs()
    jobs = []
    for split, cs in convs.items():
        for which in ("phone", "door"):
            for b in range(0, len(cs), 10):
                chunk = [(f"{split}_{i:04d}", c) for i, c in enumerate(cs[b:b + 10], start=b)]
                jobs.append((split, which, b, chunk))

    def one(job):
        split, which, b, chunk = job
        desc, sound, fields = CONV_EVENTS[which]
        text = "\n".join(f"[{cid}] The person asks: {c['user_request']} The assistant answers: {c['agent_answer']}"
                         for cid, c in chunk)
        out, u = call(key, CONV_PROMPT.format(n=len(chunk), event_desc=desc, fields=fields, sound=sound, convs=text),
                      f"conv_{which}", f"{LINES}/raw/conv_{which}_{split}_{b:04d}.json")
        return which, out["items"], u

    usage, res = {}, {"phone": {}, "door": {}}
    with ThreadPoolExecutor(workers) as ex:
        for which, items, u in ex.map(one, jobs):
            add_usage(usage, u)
            for it in items:
                res[which][it["id"]] = {k: v for k, v in it.items() if k != "id"}
    json.dump(res, open(f"{LINES}/convlines_candidates.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("convlines:", {k: len(v) for k, v in res.items()})
    return usage


def run_episodes(key, workers, second=False, pilot=False):
    import numpy as np
    os.makedirs(f"{EPIS}/raw", exist_ok=True)
    convs = load_convs()
    rng = np.random.default_rng(SEED + (7 if second else 0))
    py = random.Random(SEED + (7 if second else 0))
    plan = []
    counts = {"test": 100, "replication": 100} if second else {"train": 900, "dev": 200, "test": 600,
                                                                 "replication": 600}
    for split, n in counts.items():
        sub = episode_plan(split, convs[split], n, _Mix(rng, py), prompt_version=2 if second else 1)
        if second:                                         # second-prompt episodes: their own conversations order
            order = py.sample(range(len(convs[split])), n)
            for s, ci in zip(sub, order):
                s["conv"] = ci
        plan += sub
    name = "plan2" if second else "plan"
    json.dump(plan, open(f"{EPIS}/{name}.json", "w", encoding="utf-8"), indent=1)
    template = EPISODE_PROMPT2 if second else EPISODE_PROMPT
    if pilot:                                              # train only: one episode per type (+ silent door-going)
        picked, seen = [], set()
        for s in plan:
            tag = (s["type"], s.get("silent"))
            if s["split"] == "train" and tag not in seen and (s["type"] != "visitor" or len(seen) < 9):
                seen.add(tag)
                picked.append(s)
        plan = picked

    def one(s):
        c = convs[s["split"]][s["conv"]]
        prompt = template.format(request=c["user_request"], answer=c["agent_answer"], plan=plan_text(s, c["topic"]),
                                 rules=EPISODE_RULES)
        out, u = call(key, prompt, "episode", f"{EPIS}/raw/{s['episode']}.json")
        return s["episode"], out["turns"], u

    usage, res = {}, {}
    with ThreadPoolExecutor(workers) as ex:
        for k, (eid, turns, u) in enumerate(ex.map(one, plan)):
            add_usage(usage, u)
            res[eid] = turns
            if k % 100 == 0:
                print(f"episodes {k}/{len(plan)}", flush=True)
    out = "pilot" if pilot else ("episodes2" if second else "episodes")
    json.dump(res, open(f"{EPIS}/{out}_candidates.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("episodes:", len(res))
    if pilot:
        for s in plan:
            print("\n===", s["episode"], {k: v for k, v in s.items() if k not in ("split", "episode")})
            for t in res[s["episode"]]:
                if t["kind"] == "speech":
                    who = t["speaker"] + (f"->{t['addressee']}/{t['act']}" if t["speaker"] == "user" else "")
                    print(f"  {'~' if t['overlaps_assistant'] else ' '} {who}: {t['text']}")
                else:
                    print(f"  {'~' if t['overlaps_assistant'] else ' '} [{t['sound'] or t['pause']}]")
    return usage


def run_regen(key, workers):
    """Rewrite, once and with a new raw id (new sample), every episode that failed the structure check
    (data/episodes_v04/validation.json) or the causal check (results/step0_v04/episode_check.json). The rewritten
    script keeps its episode id and goes to episodes_regen_candidates.json; only these are checked again."""
    convs = load_convs()
    plans = {s["episode"]: s for f in (f"{EPIS}/plan.json", f"{EPIS}/plan2.json") if os.path.exists(f)
             for s in json.load(open(f, encoding="utf-8"))}
    val = json.load(open(f"{EPIS}/validation.json", encoding="utf-8"))
    fail = {e for e, v in val.items() if v}
    chk = "results/step0_v04/episode_check.json"
    if os.path.exists(chk):
        fail |= set(json.load(open(chk, encoding="utf-8"))["failed_points"])
    todo = sorted(fail)

    def one(eid):
        s = plans[eid]
        c = convs[s["split"]][s["conv"]]
        template = EPISODE_PROMPT2 if s.get("prompt_version") == 2 else EPISODE_PROMPT
        prompt = template.format(request=c["user_request"], answer=c["agent_answer"], plan=plan_text(s, c["topic"]),
                                 rules=EPISODE_RULES)
        out, u = call(key, prompt, "episode", f"{EPIS}/raw/{eid}_r1.json")
        return eid, out["turns"], u

    usage, res = {}, {}
    with ThreadPoolExecutor(workers) as ex:
        for eid, turns, u in ex.map(one, todo):
            add_usage(usage, u)
            res[eid] = turns
    json.dump(res, open(f"{EPIS}/episodes_regen_candidates.json", "w", encoding="utf-8"), indent=1,
              ensure_ascii=False)
    print("regenerated:", len(res))
    return usage


class _Mix:
    """numpy integers + python choice/random behind one seeded object."""
    def __init__(self, rng, py):
        self.rng, self.py = rng, py

    def integers(self, a, b):
        return self.rng.integers(a, b)

    def random(self):
        return self.py.random()

    def choice(self, xs):
        return self.py.choice(xs)


def main(key_path, what, workers="8"):
    key = next(str(v).strip() for k, v in json.load(open(key_path, encoding="utf-8")).items()
               if k in ("OPENAI_API_KEY", "api_key") and v)
    w = int(workers)
    usage = {"pools": run_pools, "convlines": lambda k: run_convlines(k, w),
             "episodes": lambda k: run_episodes(k, w), "episodes2": lambda k: run_episodes(k, w, second=True),
             "pilot": lambda k: run_episodes(k, w, pilot=True), "regen": lambda k: run_regen(k, w)}[what](key)
    print("usage", usage, "approx cost $",
          round(usage.get("input_tokens", 0) * 2e-6 + usage.get("output_tokens", 0) * 10e-6, 2))


if __name__ == "__main__":
    main(*sys.argv[1:4])
